/** Bitmap font (5x7 glyphs drawn by code in the Alpha). */
export const FONT = {
	pixel: 'font.pixel',
} as const;

/** Icon textures are `icon.<id>` (16x16). */
export function iconKey(id: string): string {
	return `icon.${id}`;
}

